package dev.terashima.yomitorirss.feature.library

internal val KINDLE_WEBVIEW_COLLECT_SCRIPT = """
(async()=>{const bridge=window.YomitoriLibraryBridge;const post=(type,payload)=>bridge.postMessage(JSON.stringify(Object.assign({type:type},payload||{})));const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));const send=async output=>{const json=JSON.stringify(output);const bytes=new TextEncoder().encode(json).length;if(bytes>26214400)throw Error('取得データが25MBを超えました');const size=32768,total=Math.ceil(json.length/size),session=Date.now().toString(36)+Math.random().toString(36).slice(2);post('result-start',{session:session,total:total,byteLength:bytes});for(let i=0;i<total;i++){post('result-chunk',{session:session,index:i,total:total,data:json.slice(i*size,(i+1)*size)});if(i%20===19)await pause(0)}post('result-end',{session:session})};try{if(!bridge||typeof bridge.postMessage!=='function')throw Error('アプリとの通信を開始できません');const d=document;const fetchAll=async(type,token='')=>{const items=[];let page=1;const seen=new Set;for(;;){if(seen.has(token))break;seen.add(token);post('progress',{message:type+' '+page+'ページ / '+items.length+'件'});const u=new URL('/kindle-library/search',location.origin);u.searchParams.set('query','');u.searchParams.set('libraryType',type);u.searchParams.set('sortType','acquisition_asc');u.searchParams.set('querySize','50');if(token!=='')u.searchParams.set('paginationToken',token);const response=await fetch(u,{credentials:'include',cache:'no-store'});if(!response.ok)throw Error(type+' HTTP '+response.status);const body=await response.json(),pageItems=body.itemsList||[];items.push(...pageItems);const next=body.paginationToken==null?'':String(body.paginationToken);if(!pageItems.length||!next||next===token)break;token=next;page++;await pause(80)}return items};const names=new Map;const collectNames=()=>d.querySelectorAll('a[id^="library-series-item-option-"][href*="/kindle-library/manga/collection/"]').forEach(a=>{const match=a.href.match(/\/collection\/([^?/#]+)/),name=a.querySelector('img')?.alt?.trim();if(match&&name)names.set(match[1],name)});const library=d.getElementById('library');if(!library)throw Error('#library が見つかりません。シリーズ表示を開いてください');let last=-1,stable=0;for(let i=0;i<150&&stable<6;i++){collectNames();post('progress',{message:'シリーズ名 '+names.size+'件'});library.scrollTop=library.scrollHeight;await pause(300);stable=names.size===last?stable+1:0;last=names.size}collectNames();const booksRaw=await fetchAll('BOOKS');const mangaRaw=await fetchAll('MANGA','0');const seriesByAsin=new Map;mangaRaw.forEach(item=>{const series=item.parentSeriesInfo;if(item.asin&&series?.asin)seriesByAsin.set(String(item.asin),{id:String(series.asin),name:names.get(String(series.asin))||null,position:series.positionInSeries??null})});const authors=value=>[...new Set((Array.isArray(value)?value:[]).flatMap(x=>String(x).split(':')).map(x=>x.trim()).filter(Boolean))];const byAsin=new Map;booksRaw.forEach(item=>{if(!item.asin||item.resourceType!=='EBOOK')return;const asin=String(item.asin);byAsin.set(asin,{asin:asin,title:String(item.title||'').trim(),authors:authors(item.authors),coverUrl:item.productUrl?String(item.productUrl):null,series:seriesByAsin.get(asin)||null})});const books=[...byAsin.values()];const output={format:'kindle-library-export',version:1,exportedAt:new Date().toISOString(),count:books.length,stats:{seriesNames:names.size,seriesBooks:books.filter(x=>x.series).length,seriesBooksWithName:books.filter(x=>x.series?.name).length,missingCover:books.filter(x=>!x.coverUrl).length},books:books};post('progress',{message:books.length+'冊をアプリへ渡しています'});await send(output)}catch(error){post('error',{message:'Kindle 取得失敗: '+(error?.message||String(error))})}})();
""".trimIndent()

internal val KINDLE_PERSONAL_DOCUMENT_WEBVIEW_COLLECT_SCRIPT = """
(async()=>{const bridge=window.YomitoriLibraryBridge;const post=(type,payload)=>bridge.postMessage(JSON.stringify(Object.assign({type:type},payload||{})));const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));const send=async output=>{const json=JSON.stringify(output);const bytes=new TextEncoder().encode(json).length;if(bytes>26214400)throw Error('取得データが25MBを超えました');const size=32768,total=Math.ceil(json.length/size),session=Date.now().toString(36)+Math.random().toString(36).slice(2);post('result-start',{session:session,total:total,byteLength:bytes});for(let i=0;i<total;i++){post('result-chunk',{session:session,index:i,total:total,data:json.slice(i*size,(i+1)*size)});if(i%20===19)await pause(0)}post('result-end',{session:session})};try{if(!bridge||typeof bridge.postMessage!=='function')throw Error('アプリとの通信を開始できません');const token=String(window.csrfToken||'');if(!token)throw Error('Amazon の認証情報を確認できません。ページを再読み込みしてください');const decode=value=>{const area=document.createElement('textarea');area.innerHTML=value||'';return area.value};const raw=[];let startIndex=0,page=1;const batchSize=100;for(;;){post('progress',{message:'Personal Document '+page+'ページ / '+raw.length+'件'});const query={contentType:'KindlePDoc',contentCategoryReference:'pdocs',itemStatusList:['Active'],fetchCriteria:{sortOrder:'DESCENDING',sortIndex:'DATE',startIndex:startIndex,batchSize:batchSize,totalContentCount:-1},surfaceType:'Mobile'};const params=new URLSearchParams({activity:'GetContentOwnershipData',activityInput:JSON.stringify(query),clientId:'MYCD_WebService',csrfToken:token});const response=await fetch('/hz/mycd/digital-console/ajax',{method:'POST',credentials:'include',cache:'no-store',body:params});if(!response.ok)throw Error('MYCD HTTP '+response.status);const body=await response.json(),group=body.GetContentOwnershipData||{},items=Array.isArray(group.items)?group.items:[];raw.push(...items);const total=Number(group.numberOfItems);if(!items.length||(Number.isFinite(total)&&raw.length>=total))break;startIndex+=items.length;page++;await pause(80)}const byId=new Map;raw.forEach(item=>{const id=String(item.asin||'').trim().toUpperCase(),title=decode(item.title).trim();if(!/^[A-Z0-9]{32}$/.test(id)||!title)return;const author=decode(item.author).trim();byId.set(id,{id:id,title:title,authors:author&&author!=='Unknown'?[author]:[],contentType:item.contentType?String(item.contentType):null,acquiredAt:item.acquiredTime?String(item.acquiredTime):null})});const books=[...byId.values()];if(!books.length)throw Error('Personal Document が見つかりませんでした');const output={format:'kindle-personal-library-export',version:1,exportedAt:new Date().toISOString(),count:books.length,books:books};post('progress',{message:books.length+'件をアプリへ渡しています'});await send(output)}catch(error){post('error',{message:'Personal Document 取得失敗: '+(error?.message||String(error))})}})();
""".trimIndent()

internal val AUDIBLE_WEBVIEW_COLLECT_SCRIPT = """
(async()=>{const bridge=window.YomitoriLibraryBridge;const post=(type,payload)=>bridge.postMessage(JSON.stringify(Object.assign({type:type},payload||{})));try{if(!bridge||typeof bridge.postMessage!=='function')throw Error('アプリとの通信を開始できません');const asins=new Set;for(let page=1;page<=200;page++){post('progress',{message:'Audible ライブラリー '+page+'ページ / '+asins.size+'件'});const response=await fetch('/library/titles?page='+page,{credentials:'include',cache:'no-store'});if(!response.ok)break;const doc=new DOMParser().parseFromString(await response.text(),'text/html');const found=[...doc.querySelectorAll('[data-asin]')].map(element=>element.dataset.asin).filter(value=>/^[A-Z0-9]{10}$/i.test(value));const before=asins.size;found.forEach(value=>asins.add(value.toUpperCase()));if(!found.length||asins.size===before)break}const all=[...asins];if(!all.length)throw Error('ASIN を取得できませんでした');const first=all.slice(0,50),rest=all.slice(50),groups='contributors,media,product_desc,product_extended_attrs,relationships';post('progress',{message:all.length+'件の ASIN を取得しました。カタログへ移動します'});location.href='https://api.audible.co.jp/1.0/catalog/products?asins='+first.join(',')+'&response_groups='+groups+'&image_sizes=500#rest='+rest.join(',')}catch(error){post('error',{message:'Audible 取得失敗: '+(error?.message||String(error))})}})();
""".trimIndent()

internal val AUDIBLE_WEBVIEW_EXPORT_SCRIPT = """
(async()=>{const bridge=window.YomitoriLibraryBridge;const post=(type,payload)=>bridge.postMessage(JSON.stringify(Object.assign({type:type},payload||{})));const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));const send=async output=>{const json=JSON.stringify(output);const bytes=new TextEncoder().encode(json).length;if(bytes>26214400)throw Error('取得データが25MBを超えました');const size=32768,total=Math.ceil(json.length/size),session=Date.now().toString(36)+Math.random().toString(36).slice(2);post('result-start',{session:session,total:total,byteLength:bytes});for(let i=0;i<total;i++){post('result-chunk',{session:session,index:i,total:total,data:json.slice(i*size,(i+1)*size)});if(i%20===19)await pause(0)}post('result-end',{session:session})};try{if(!bridge||typeof bridge.postMessage!=='function')throw Error('アプリとの通信を開始できません');let products=JSON.parse(document.body.innerText).products||[];const rest=(location.hash.match(/rest=([^#]+)/)?.[1]||'').split(',').filter(Boolean),groups='contributors,media,product_desc,product_extended_attrs,relationships';for(let i=0;i<rest.length;i+=50){post('progress',{message:'Audible カタログ '+Math.min(i+50,rest.length)+' / '+rest.length+'件'});const batch=rest.slice(i,i+50);const response=await fetch('/1.0/catalog/products?asins='+batch.join(',')+'&response_groups='+groups+'&image_sizes=500',{credentials:'include',cache:'no-store'});if(!response.ok)throw Error('Catalog HTTP '+response.status);const body=await response.json();products.push(...(body.products||[]))}const plain=html=>{if(!html)return null;const doc=new DOMParser().parseFromString('<body>'+html,'text/html');return doc.body.textContent.replace(/\s+/g,' ').trim()},cover=product=>product.product_images?.['500']||Object.entries(product.product_images||{}).sort((a,b)=>+b[0]-+a[0])[0]?.[1]||null,series=new Map;for(let i=0;i<products.length;i+=5){post('progress',{message:'シリーズ情報 '+Math.min(i+5,products.length)+' / '+products.length+'件'});await Promise.all(products.slice(i,i+5).map(async product=>{try{const response=await fetch('/1.0/catalog/products/'+product.asin+'?response_groups=series',{credentials:'include',cache:'no-store'});if(!response.ok)return;const body=await response.json(),item=body.product?.series?.[0];if(!item)return;const name=item.title||item.name||null,value=parseInt(item.sequence),position=Number.isFinite(value)?value:null,id=/^[A-Z0-9]{10}$/i.test(item.asin||'')?String(item.asin).toUpperCase():null;if((name||id)&&!(name&&position==null&&/(出版社|出版|パブリッシング|publishing|press)$/i.test(name)))series.set(product.asin,{id:id,name:name,position:position})}catch(_){}}))}const books=products.map(product=>({asin:product.asin,title:product.title,subtitle:product.subtitle||null,authors:(product.authors||[]).map(x=>x.name),narrators:(product.narrators||[]).map(x=>x.name),publisher:product.publisher_name||product.publication_name||null,publishedDate:product.release_date||product.issue_date||null,description:plain(product.merchandising_summary||product.publisher_summary),coverUrl:cover(product),durationMinutes:product.runtime_length_min||null,series:series.get(product.asin)||null,productUrl:'https://www.audible.co.jp/pd/'+product.asin}));const output={format:'audible-library-export',version:1,exportedAt:new Date().toISOString(),count:books.length,stats:{seriesBooks:books.filter(x=>x.series).length,missingCover:books.filter(x=>!x.coverUrl).length,missingPublisher:books.filter(x=>!x.publisher).length},books:books};post('progress',{message:books.length+'冊をアプリへ渡しています'});await send(output)}catch(error){post('error',{message:'Audible 取得失敗: '+(error?.message||String(error))})}})();
""".trimIndent()
